<?php
declare(strict_types=1);
final class ImportValidationService{
 public function rows(string$path,string$type):array{$h=fopen($path,'rb');if(!$h)throw new RuntimeException('No fue posible leer el archivo.');$header=fgetcsv($h,0,',');if(!$header)throw new InvalidArgumentException('El CSV está vacío.');$header=array_map(fn($v)=>trim((string)$v),$header);$allowed=$type==='perfumes'?['external_id','name','slug','brand','brand_slug','primary_category','gender','concentration','olfactory_family','short_description','full_description','availability_status','show_price','price_from','price_text','launch_year','perfumer','country_of_origin','season','occasion','intensity','longevity','sillage','tags','top_notes','heart_notes','base_notes','general_notes','presentations','is_featured','is_new','sort_order','meta_title','meta_description','status']:['name','slug','description','is_active','sort_order'];$unknown=array_diff($header,$allowed);if($unknown)throw new InvalidArgumentException('Columnas no permitidas: '.implode(',',$unknown));$rows=[];$line=1;$max=Env::int('IMPORT_MAX_ROWS',10000);while(($data=fgetcsv($h,0,','))!==false){$line++;if(count($rows)>=$max)throw new InvalidArgumentException('El archivo excede el máximo de filas.');$row=array_combine($header,array_pad($data,count($header),''));$errors=[];$name=trim((string)($row['name']??''));if($name==='')$errors[]='Falta name.';if($type==='perfumes'){$row['status']='borrador';$row['is_published']='0';if(!in_array($row['availability_status']??'pendiente',PerfumeValidator::AVAILABILITY,true)){$row['availability_status']='pendiente';$errors[]='Disponibilidad inválida; se usará pendiente.';}$row['show_price']=($row['show_price']??'')==='1'?'1':'0';}$rows[]=['row_number'=>$line,'raw'=>$row,'errors'=>$errors,'status'=>$errors?'error':'valid'];}fclose($h);return$rows;}
}
